package com.lyra.studio; import android.app.Activity; import android.view.View; import android.view.WindowManager; import android.webkit.WebChromeClient; import android.webkit.WebView; import android.webkit.WebViewClient; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; @DesignerComponent(version = 1, description = "Componente WebView que se ajusta automaticamente ao teclado virtual.", category = ComponentCategory.EXTENSION, nonVisible = false, iconName = "images/extension.png") @SimpleObject(external = true) public class ResponsiveWebView extends AndroidViewComponent { private WebView webView; private Activity activity; /* Construtor do componente */ public ResponsiveWebView(ComponentContainer container) { super(container); this.activity = container.$context(); /* Inicializa o WebView */ this.webView = new WebView(this.activity); this.webView.getSettings().setJavaScriptEnabled(true); /* Habilita o JavaScript */ this.webView.getSettings().setDomStorageEnabled(true); /* Habilita o DOM */ this.webView.setWebViewClient(new WebViewClient()); this.webView.setWebChromeClient(new WebChromeClient()); /* Adiciona a View ao container */ container.$add(this); /* Ajusta a janela da Activity para redimensionar quando o teclado abrir */ this.activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } /* Retorna a view nativa */ @Override public View getView() { return webView; } /* Funcao para carregar uma URL */ @SimpleFunction(description = "Carrega uma URL no WebView.") public void IrParaUrl(String url) { webView.loadUrl(url); } /* Funcao para recarregar a pagina */ @SimpleFunction(description = "Recarrega a pagina atual.") public void Recarregar() { webView.reload(); } /* Funcao para alternar o modo de ajuste do teclado */ @SimpleFunction(description = "Habilita ou desabilita o ajuste automatico do layout para o teclado virtual.") public void AjustarAoTeclado(boolean ajustar) { if (ajustar) { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } else { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_PAN); } } }